  # Filled Order Snapshot
  # ---------------------------------------------------------------------------------------------
  def filled_order_snapshot(self, trade: "Trade") -> tuple:
    filled_orders = trade.select_filled_orders()
    filled_entries = []
    filled_exits = []
    append_entry = filled_entries.append
    append_exit = filled_exits.append
    entry_side = trade.entry_side
    exit_side = trade.exit_side
    for order in filled_orders:
      order_side = order.ft_order_side
      if order_side == entry_side:
        append_entry(order)
      elif order_side == exit_side:
        append_exit(order)
    return filled_orders, filled_entries, filled_exits

  @staticmethod
  def _bad_trade_controller_ema_gap_and_adverse_move(
    trade: "Trade", current_rate: float, last_candle, filled_entries: "Orders"
  ) -> tuple:
    """Return position-signed daily EMA gap and adverse move from the first filled entry."""
    ema_50_1d = last_candle.get("EMA_50_1d")
    ema_200_1d = last_candle.get("EMA_200_1d")
    if (
      ema_50_1d is None
      or ema_200_1d is None
      or not np.isfinite(ema_50_1d)
      or not np.isfinite(ema_200_1d)
      or ema_200_1d <= 0.0
    ):
      daily_ema_gap_pct = None
    else:
      daily_ema_gap_pct = (ema_50_1d / ema_200_1d - 1.0) * 100.0
      if trade.is_short:
        daily_ema_gap_pct = -daily_ema_gap_pct

    if not filled_entries:
      return daily_ema_gap_pct, None
    first_entry_rate = filled_entries[0].safe_price
    if first_entry_rate is None or not np.isfinite(first_entry_rate) or first_entry_rate <= 0.0:
      return daily_ema_gap_pct, None
    first_entry_adverse_move_pct = (
      ((current_rate - first_entry_rate) if trade.is_short else (first_entry_rate - current_rate))
      / first_entry_rate
      * 100.0
    )
    return daily_ema_gap_pct, first_entry_adverse_move_pct

  def _bad_trade_controller_exit_reason(
    self,
    trade: "Trade",
    current_time: "datetime",
    current_rate: float,
    last_candle,
    filled_entries: "Orders",
  ) -> Optional[str]:
    """Return a structure-break or stale-position exit reason."""
    daily_ema_gap_pct, first_entry_adverse_move_pct = self._bad_trade_controller_ema_gap_and_adverse_move(
      trade, current_rate, last_candle, filled_entries
    )
    if first_entry_adverse_move_pct is None or not np.isfinite(first_entry_adverse_move_pct):
      return None
    if (
      self.bad_trade_controller_structure_break_exit_enable
      and daily_ema_gap_pct is not None
      and daily_ema_gap_pct <= -self.bad_trade_controller_structure_break_ema_gap_pct
      and first_entry_adverse_move_pct >= self.bad_trade_controller_structure_break_min_adverse_move_pct
    ):
      return f"exit_bad_trade_broken_{first_entry_adverse_move_pct:.0f}pct"

    daily_range_pct_14_1d = last_candle.get("RANGE_PCT_14_1d")
    trade_age_days = (current_time - trade.open_date_utc).total_seconds() / 86400.0
    if (
      self.bad_trade_controller_stale_exit_enable
      and daily_range_pct_14_1d is not None
      and np.isfinite(daily_range_pct_14_1d)
      and daily_range_pct_14_1d < self.bad_trade_controller_stale_max_daily_range_pct
      and first_entry_adverse_move_pct >= self.bad_trade_controller_stale_min_adverse_move_pct
      and trade_age_days >= self.bad_trade_controller_stale_min_age_days
    ):
      return f"exit_bad_trade_abandon_{trade_age_days:.0f}d"
    return None

  def trade_order_state(self, trade: "Trade") -> tuple:
    orders = trade.orders

    last_order = orders[-1] if orders else None
    return (
      len(orders),
      getattr(last_order, "id", None),
      getattr(last_order, "status", None),
      getattr(last_order, "filled", None),
    )

  def cache_backtest_profit_snapshot(
    self,
    trade: "Trade",
    current_time: "datetime",
    exit_rate: float,
    filled_orders: "Orders",
    filled_entries: "Orders",
    filled_exits: "Orders",
    profit_values: tuple,
  ) -> None:
    if not self.is_backtest_mode():
      return

    trade_key = trade.id if trade.id is not None else id(trade)
    self._backtest_profit_snapshot = (
      trade_key,
      current_time,
      exit_rate,
      self.trade_order_state(trade),
      filled_orders,
      filled_entries,
      filled_exits,
      profit_values,
    )

  def backtest_profit_snapshot(self, trade: "Trade", current_time: "datetime", exit_rate: float) -> tuple | None:
    if not self.is_backtest_mode():
      return None

    snapshot = getattr(self, "_backtest_profit_snapshot", None)
    if snapshot is None:
      return None

    (
      snapshot_trade_id,
      snapshot_time,
      snapshot_exit_rate,
      snapshot_order_state,
      filled_orders,
      filled_entries,
      filled_exits,
      profit_values,
    ) = snapshot
    trade_key = trade.id if trade.id is not None else id(trade)
    if (
      snapshot_trade_id == trade_key
      and snapshot_time == current_time
      and snapshot_exit_rate == exit_rate
      and snapshot_order_state == self.trade_order_state(trade)
    ):
      return filled_orders, filled_entries, filled_exits, profit_values

    return None

  def profit_or_order_snapshot(self, trade: "Trade", current_time: "datetime", exit_rate: float) -> tuple:
    profit_snapshot = self.backtest_profit_snapshot(trade, current_time, exit_rate)
    if profit_snapshot is not None:
      return profit_snapshot

    filled_orders, filled_entries, filled_exits = self.filled_order_snapshot(trade)
    return filled_orders, filled_entries, filled_exits, None

  # Calc Total Profit
  # ---------------------------------------------------------------------------------------------
  def calc_total_profit(
    self, trade: "Trade", filled_entries: "Orders", filled_exits: "Orders", exit_rate: float
  ) -> tuple:
    """
    Calculates the absolute profit for open trades.

    :param trade: trade object.
    :param filled_entries: Filled entries list.
    :param filled_exits: Filled exits list.
    :param exit_rate: The exit rate.
    :return tuple: The total profit in stake, ratio, ratio based on current stake, and ratio based on the first entry stake.
    """
    custom_fee_open_rate = self.custom_fee_open_rate
    custom_fee_close_rate = self.custom_fee_close_rate
    is_futures_mode = self.is_futures_mode

    fee_open_rate = trade.fee_open if custom_fee_open_rate is None else custom_fee_open_rate
    fee_close_rate = trade.fee_close if custom_fee_close_rate is None else custom_fee_close_rate

    total_amount = 0.0
    total_stake = 0.0
    total_profit = 0.0
    if trade.is_short:
      fee_open_multiplier = 1 - fee_open_rate
      fee_close_multiplier = 1 + fee_close_rate
      for entry_order in filled_entries:
        filled = entry_order.safe_filled
        entry_stake = filled * entry_order.safe_price * fee_open_multiplier
        total_amount += filled
        total_stake += entry_stake
        total_profit += entry_stake
      for exit_order in filled_exits:
        filled = exit_order.safe_filled
        exit_stake = filled * exit_order.safe_price * fee_close_multiplier
        total_amount -= filled
        total_profit -= exit_stake
      current_stake = total_amount * exit_rate * fee_close_multiplier
      total_profit -= current_stake
    else:
      fee_open_multiplier = 1 + fee_open_rate
      fee_close_multiplier = 1 - fee_close_rate
      for entry_order in filled_entries:
        filled = entry_order.safe_filled
        entry_stake = filled * entry_order.safe_price * fee_open_multiplier
        total_amount += filled
        total_stake += entry_stake
        total_profit -= entry_stake
      for exit_order in filled_exits:
        filled = exit_order.safe_filled
        exit_stake = filled * exit_order.safe_price * fee_close_multiplier
        total_amount -= filled
        total_profit += exit_stake
      current_stake = total_amount * exit_rate * fee_close_multiplier
      total_profit += current_stake
    if is_futures_mode and trade.funding_fees is not None:
      total_profit += trade.funding_fees
    total_profit_ratio = total_profit / total_stake
    current_profit_ratio = total_profit / current_stake
    init_profit_ratio = total_profit / (filled_entries[0].safe_filled * filled_entries[0].safe_price)
    return total_profit, total_profit_ratio, current_profit_ratio, init_profit_ratio

  @staticmethod
  def scale_stakes_for_min_stake(stakes, slice_amount, min_stake, stake_leverage, trade_leverage):
    if (slice_amount * stakes[0] / stake_leverage) >= min_stake:
      return stakes

    multi = min_stake / slice_amount / stakes[0] * trade_leverage
    return [stake * multi for stake in stakes]

  # Custom Exit
  # ---------------------------------------------------------------------------------------------
  def custom_exit(
    self, pair: str, trade: "Trade", current_time: "datetime", current_rate: float, current_profit: float, **kwargs
  ):
    trade_is_short = trade.is_short

    long_normal_mode_tags = self.long_normal_mode_tags
    long_pump_mode_tags = self.long_pump_mode_tags
    long_quick_mode_tags = self.long_quick_mode_tags
    long_rebuy_mode_tags = self.long_rebuy_mode_tags
    long_rebuy_grind_mode_tags = self.long_rebuy_grind_mode_tags
    long_high_profit_mode_tags = self.long_high_profit_mode_tags
    long_rapid_mode_tags = self.long_rapid_mode_tags
    long_rapid_rebuy_grind_scalp_mode_tags = self.long_rapid_rebuy_grind_scalp_mode_tags
    long_grind_mode_tags = self.long_grind_mode_tags
    long_btc_mode_tags = self.long_btc_mode_tags
    long_top_coins_mode_tags = self.long_top_coins_mode_tags
    long_scalp_mode_tags = self.long_scalp_mode_tags
    long_scalp_rebuy_grind_mode_tags = self.long_scalp_rebuy_grind_mode_tags
    long_known_mode_tags = self.long_known_mode_tags
    short_normal_mode_tags = self.short_normal_mode_tags
    short_pump_mode_tags = self.short_pump_mode_tags
    short_quick_mode_tags = self.short_quick_mode_tags
    short_rebuy_mode_tags = self.short_rebuy_mode_tags
    short_high_profit_mode_tags = self.short_high_profit_mode_tags
    short_rapid_mode_tags = self.short_rapid_mode_tags
    short_top_coins_mode_tags = self.short_top_coins_mode_tags
    short_scalp_mode_tags = self.short_scalp_mode_tags
    short_scalp_rebuy_grind_mode_tags = self.short_scalp_rebuy_grind_mode_tags
    short_exit_known_mode_tags = self.short_exit_known_mode_tags

    calc_total_profit = self.calc_total_profit
    cache_backtest_profit_snapshot = self.cache_backtest_profit_snapshot
    filled_order_snapshot = self.filled_order_snapshot
    long_exit_normal = self.long_exit_normal
    long_exit_pump = self.long_exit_pump
    long_exit_quick = self.long_exit_quick
    short_exit_normal = self.short_exit_normal

    df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
    if len(df) < 2:
      return None
    last_candle = df.iloc[-1]
    previous_candle_1 = df.iloc[-2]

    enter_tag = "empty"
    if hasattr(trade, "enter_tag"):
      trade_enter_tag = trade.enter_tag
      if trade_enter_tag is not None:
        enter_tag = trade_enter_tag
    enter_tags = enter_tag.split()

    filled_orders, filled_entries, filled_exits = filled_order_snapshot(trade)

    profit_stake = 0.0
    profit_ratio = 0.0
    profit_current_stake_ratio = 0.0
    profit_init_ratio = 0.0
    profit_values = calc_total_profit(trade, filled_entries, filled_exits, current_rate)
    profit_stake, profit_ratio, profit_current_stake_ratio, profit_init_ratio = profit_values
    cache_backtest_profit_snapshot(
      trade, current_time, current_rate, filled_orders, filled_entries, filled_exits, profit_values
    )

    system_version = trade.get_custom_data(key="system_version")
    bad_trade_exit_enable = (
      self.system_v4_bad_trade_exit_enable
      if system_version == self.system_v4_name
      else self.legacy_system_bad_trade_exit_enable
    )
    if bad_trade_exit_enable and current_profit < 0.0:
      bad_trade_exit_reason = self._bad_trade_controller_exit_reason(
        trade, current_time, current_rate, last_candle, filled_entries
      )
      if bad_trade_exit_reason is not None:
        return f"{bad_trade_exit_reason} ( {enter_tag})"

    # Signal 192 (Quad pullback long) tight doom stop: every 192 loss bottoms at a
    # 11.8-14% price drop (the shared 0.35 doom threshold) while winners' max adverse
    # excursion sits below 9.63% price. Scoping 192's doom to -0.30 margin (~10% price
    # at 3x, ~30% at 1x) flips the tag net-positive. NOTE: this fires on ANY trade
    # carrying 192 as one of several tags, and it returns before long_exit_normal, so
    # for 192 it pre-empts the de-risk ladder (measured on a gms0 replica with derisk
    # off; production runs derisk on, where the ladder exists for exactly this zone).
    # On spot the -0.30 is looser than the existing doom thresholds (0.12 spot / 0.35
    # futures) and effectively never binds.
    if "192" in enter_tags and current_profit <= -0.30:
      return f"exit_long_normal_stoploss_doom ( {enter_tag})"

    max_profit = 0.0
    max_loss = 0.0

    # Long Normal mode
    if any(c in long_normal_mode_tags for c in enter_tags):
      sell, signal_name = long_exit_normal(
        pair,
        current_rate,
        profit_stake,
        profit_ratio,
        profit_current_stake_ratio,
        profit_init_ratio,
        max_profit,
        max_loss,
        filled_orders,
        filled_entries,
        filled_exits,
        last_candle,
        previous_candle_1,
        trade,
        current_time,
        enter_tags,
      )
      if sell and (signal_name is not None):
        return f"{signal_name} ( {enter_tag})"

    # Long Pump mode
