  # Coin Pair Indicator Switch Case
  # ---------------------------------------------------------------------------------------------
  def info_switcher(self, metadata: dict, info_timeframe) -> DataFrame:
    if info_timeframe == "1d":
      return self.informative_1d_indicators(metadata, info_timeframe)
    elif info_timeframe == "4h":
      return self.informative_4h_indicators(metadata, info_timeframe)
    elif info_timeframe == "1h":
      return self.informative_1h_indicators(metadata, info_timeframe)
    elif info_timeframe == "15m":
      return self.informative_15m_indicators(metadata, info_timeframe)
    else:
      raise RuntimeError(f"{info_timeframe} not supported as informative timeframe for BTC pair.")

  # BTC Indicator Switch Case
  # ---------------------------------------------------------------------------------------------
  def btc_info_switcher(self, btc_pair: str, btc_info_timeframe) -> DataFrame:
    # if btc_info_timeframe == "1d":
    # return self.btc_informative_1d_indicators(btc_pair, btc_info_timeframe)
    if btc_info_timeframe == "4h":
      return self.btc_informative_4h_indicators(btc_pair, btc_info_timeframe)
    # elif btc_info_timeframe == "1h":
    # return self.btc_informative_1h_indicators(btc_pair, btc_info_timeframe)
    # elif btc_info_timeframe == "15m":
    # return self.btc_informative_15m_indicators(btc_pair, btc_info_timeframe)
    # elif btc_info_timeframe == "5m":
    # return self.btc_informative_5m_indicators(btc_pair, btc_info_timeframe)
    else:
      raise RuntimeError(f"{btc_info_timeframe} not supported as informative timeframe for BTC pair.")

  # Populate Indicators
  # ---------------------------------------------------------------------------------------------
  def populate_indicators(self, df: DataFrame, metadata: dict) -> DataFrame:
    debug = False
    debug_time = True
    if debug_time:
      tik = time.perf_counter()
    base_timeframe = self.timeframe
    prepare_informative_merge = self.prepare_informative_merge
    metadata_pair = metadata["pair"]

    # ============================================================
    # BTC INFORMATIVE (BATCH PREPARATION)
    # ============================================================
    btc_info_pair = self.btc_informative_pair()
    btc_info_timeframes = self.btc_info_timeframes
    btc_info_switcher = self.btc_info_switcher
    btc_frames = {}
    for btc_tf in btc_info_timeframes:
      btc_df = btc_info_switcher(btc_info_pair, btc_tf)
      if btc_df.empty:
        continue

      btc_df = prepare_informative_merge(btc_df)
      btc_frames[btc_tf] = btc_df

    # ============================================================
    # INFO TF (BATCH PREPARATION)
    # ============================================================
    info_timeframes = self.info_timeframes
    info_switcher = self.info_switcher
    info_frames = {}
    for info_tf in info_timeframes:
      info_df = info_switcher(metadata, info_tf)
      if info_df.empty:
        continue

      keep_ohlcv = {"open", "close"} if info_tf == "15m" else set()
      info_df = prepare_informative_merge(info_df, keep_ohlcv)
      info_frames[info_tf] = info_df

    # ============================================================
    # BTC MERGE
    # ============================================================
    for tf, frame in btc_frames.items():
      df = merge_informative_pair(df, frame, base_timeframe, tf, ffill=False)
      # BTC date is not needed. only info_tf needs it because of add_informative_ready (not yet implemented) validation(Current PR not affected by this).
      col = f"date_{tf}"
      if col in df.columns:
        df = df.drop(columns=col)

    # ============================================================
    # NORMAL INFORMATIVE MERGE
    # ============================================================
    for tf, frame in info_frames.items():
      df = merge_informative_pair(df, frame, base_timeframe, tf, ffill=False)

    # ============================================================
    # FINAL FILL ONLY AFTER ALL MERGES
    # ============================================================
    df = df.ffill()

    # ============================================================
    # POST-FFILL VALIDATION
    # ============================================================
    if debug:
      groups = {
        "INFO": self.info_timeframes,
        "BTC": self.btc_info_timeframes,
      }

      for source, tfs in groups.items():
        for tf in tfs:
          if source == "BTC":
            tf_cols = [c for c in df.columns if c.startswith("BTC_") and c.endswith(f"_{tf}")]
          else:
            tf_cols = [c for c in df.columns if not c.startswith("BTC_") and c.endswith(f"_{tf}")]

          if not tf_cols:
            continue

          recent = df[tf_cols].tail(500)
          total_nans = recent.isna().sum().sum()

          if total_nans > 0:
            log.warning("[%s] %s %s recent500 contains %s NaNs", metadata_pair, source, tf, total_nans)
          else:
            log.info("[%s] %s %s merge OK", metadata_pair, source, tf)

    # ============================================================
    # BASE TF (LAST)
    # ============================================================
    df = self.base_tf_5m_indicators(metadata, df)

    # ============================================================
    # FINAL INDICATOR VALIDATION
    # ============================================================
    if debug:
      recent = df.tail(500)
      final_nan = recent.isna().sum()
      final_nan = final_nan[final_nan > 0]
      if not final_nan.empty:
        log.warning(
          "[%s] Unexpected indicator NaNs in recent candles:\n%s",
          metadata_pair,
          final_nan.sort_values(ascending=False).to_string(),
        )

    if debug_time:
      tok_before_protections = time.perf_counter()

    np_view = lambda c: df[c].to_numpy(copy=False)
    np_shift = self.np_shift
    protection_rsi_3 = np_view("RSI_3")
    protection_rsi_3_15m = np_view("RSI_3_15m")
    protection_rsi_3_1h = np_view("RSI_3_1h")
    protection_rsi_3_4h = np_view("RSI_3_4h")
    protection_rsi_3_1d = np_view("RSI_3_1d")
    protection_rsi_14_1h = np_view("RSI_14_1h")
    protection_rsi_14_4h = np_view("RSI_14_4h")
    protection_rsi_14_1d = np_view("RSI_14_1d")
    protection_cci_20_1h = np_view("CCI_20_1h")
    protection_cci_20_4h = np_view("CCI_20_4h")
    protection_rsi_14_15m = np_view("RSI_14_15m")
    protection_stochrsik_14_14_3_3_15m = np_view("STOCHRSIk_14_14_3_3_15m")
    protection_stochrsik_14_14_3_3_1d = np_view("STOCHRSIk_14_14_3_3_1d")
    protection_aroonu_14_15m = np_view("AROONU_14_15m")
    protection_cmf_20_15m = np_view("CMF_20_15m")
    protection_aroonu_14_4h = np_view("AROONU_14_4h")
    protection_roc_9_1d = np_view("ROC_9_1d")
    protection_aroonu_14_1h = np_view("AROONU_14_1h")
    protection_stochrsik_14_14_3_3_1h = np_view("STOCHRSIk_14_14_3_3_1h")
    protection_stochrsik_14_14_3_3_4h = np_view("STOCHRSIk_14_14_3_3_4h")
    protection_roc_9_4h = np_view("ROC_9_4h")
    protection_cmf_20_1d = np_view("CMF_20_1d")
    protection_roc_9_15m = np_view("ROC_9_15m")
    protection_roc_9_1h = np_view("ROC_9_1h")
    protection_cmf_20_1h = np_view("CMF_20_1h")
    protection_cmf_20_4h = np_view("CMF_20_4h")
    protection_aroonu_14_1d = np_view("AROONU_14_1d")
    protection_mfi_14_1d = np_view("MFI_14_1d")
    protection_roc_2_1d = np_view("ROC_2_1d")
    protection_mfi_14_1h = np_view("MFI_14_1h")
    protection_mfi_14_4h = np_view("MFI_14_4h")
    protection_stochk_14_3_3_1h = np_view("STOCHk_14_3_3_1h")
    protection_stochk_14_3_3_4h = np_view("STOCHk_14_3_3_4h")
    protection_cci_20_change_pct_4h = np_view("CCI_20_change_pct_4h")
    protection_change_pct_4h = np_view("change_pct_4h")
    protection_change_pct_4h_shift_48 = np_shift(protection_change_pct_4h, 48)
    protection_top_wick_pct_4h = np_view("top_wick_pct_4h")
    protection_change_pct_1d = np_view("change_pct_1d")
    protection_change_pct_1d_shift_288 = np_shift(protection_change_pct_1d, 288)
    protection_top_wick_pct_1d = np_view("top_wick_pct_1d")
    protection_top_wick_pct_1d_shift_288 = np_shift(protection_top_wick_pct_1d, 288)
    protection_high_max_6_1d = np_view("high_max_6_1d")
    protection_low_min_6_1d = np_view("low_min_6_1d")
    protection_close = np_view("close")
    protection_high_max_6_4h = np_view("high_max_6_4h")
    protection_high_max_12_1d = np_view("high_max_12_1d")
    protection_low_min_12_1d = np_view("low_min_12_1d")
    protection_high_max_24_4h = np_view("high_max_24_4h")
