  # Populate Entry Trend
  # ---------------------------------------------------------------------------------------------
  def populate_entry_trend(self, df, metadata):
    df.loc[:, ["enter_long", "enter_short"]] = (0, 0)
    df.loc[:, "enter_tag"] = ""
    conditions = (df["volume"] > 0.0) & (df["RSI_14"] > 60.0)
    df.loc[conditions, "enter_long"] = 1
    df.loc[conditions, "enter_tag"] = "1 "
    return df

