  # Long Exit Rapid
  # ---------------------------------------------------------------------------------------------
  def long_exit_rapid(
    self,
    pair: str,
    current_rate: float,
    profit_stake: float,
    profit_ratio: float,
    profit_current_stake_ratio: float,
    profit_init_ratio: float,
    max_profit: float,
    max_loss: float,
    filled_entries,
    filled_exits,
    last_candle,
    previous_candle_1,
    trade: "Trade",
    current_time: "datetime",
    enter_tags,
  ) -> tuple:
    is_futures_mode = self.is_futures_mode
    stops_enable = self.stops_enable

    mark_profit_target = self.mark_profit_target
    set_profit_target = self._set_profit_target
    exit_profit_target = self.exit_profit_target

    is_backtest = self.is_backtest_mode()
    is_system_v3, is_system_v3_1, is_system_v3_2 = self.get_system_version_flags(trade)
    is_system_v4 = self.is_system_v4(trade)

    mode = self.long_rapid_mode_name
    cache = self.target_profit_cache
    cache_data = cache.data if cache is not None else None
    profit_target_get = cache_data.get if cache_data is not None else None
    pair_cache = profit_target_get(pair) if profit_target_get is not None else None
    previous_profit = pair_cache["profit"] if pair_cache else None
    previous_sell_reason = pair_cache["sell_reason"] if pair_cache else ""

    sell = False
    signal_name = None

    common_args = (
      mode,
      profit_init_ratio,
      max_profit,
      max_loss,
      last_candle,
      previous_candle_1,
      trade,
      current_time,
      enter_tags,
    )

    # if the profit is negative skip checking these
    if profit_init_ratio > 0.0:
      for exit_func in (
        self.long_exit_signals,
        self.long_exit_main,
        self.long_exit_williams_r,
        self.long_exit_dec,
      ):
        sell, signal_name = exit_func(*common_args)
        if sell:
          break

    # Extra exit logic
    if not sell:
      in_range = 0.09 >= profit_init_ratio > 0.005

      if in_range:
        rsi14 = last_candle["RSI_14"]
        mfi14 = last_candle["MFI_14"]
        willr14 = last_candle["WILLR_14"]
        rsi3 = last_candle["RSI_3"]
        rsi3_15m = last_candle["RSI_3_15m"]

        rapid_conditions = (
          (rsi14 > 78.0, f"exit_{mode}_rpd_1"),
          (mfi14 > 84.0, f"exit_{mode}_rpd_2"),
          (willr14 >= -0.1, f"exit_{mode}_rpd_3"),
          (
            rsi14 >= 72.0 and rsi3 > 90.0 and rsi3_15m > 90.0,
            f"exit_{mode}_rpd_4",
          ),
          (rsi3_15m > 96.0, f"exit_{mode}_rpd_5"),
          (rsi3 > 85.0 and rsi3_15m > 85.0, f"exit_{mode}_rpd_6"),
          (rsi3 > 90.0 and rsi3_15m > 80.0, f"exit_{mode}_rpd_7"),
          (rsi3 > 92.0 and rsi3_15m > 75.0, f"exit_{mode}_rpd_8"),
          (rsi3 > 94.0 and rsi3_15m > 70.0, f"exit_{mode}_rpd_9"),
          (rsi3 > 99.0, f"exit_{mode}_rpd_10"),
        )

        for condition, signal in rapid_conditions:
          if condition:
            sell, signal_name = True, signal
            break

      if not sell:
        entry_cost = filled_entries[0].safe_filled * filled_entries[0].safe_price
        leverage = trade.leverage
        stop_threshold = None
        stop_enabled = False

        if is_system_v4:
          stop_enabled = self.system_v4_stops_enable
          stop_threshold = (
            self.system_v4_stop_threshold_rapid_futures
            if is_futures_mode
            else self.system_v4_stop_threshold_rapid_spot
          )
        elif is_system_v3_2:
          stop_enabled = self.system_v3_2_stops_enable
          stop_threshold = (
            self.system_v3_2_stop_threshold_rapid_futures
            if is_futures_mode
            else self.system_v3_2_stop_threshold_rapid_spot
          )
        elif is_system_v3_1:
          stop_enabled = stops_enable
          stop_threshold = (
            self.system_v3_1_stop_threshold_rapid_futures
            if is_futures_mode
            else self.system_v3_1_stop_threshold_rapid_spot
          )
        elif is_system_v3:
          stop_enabled = stops_enable
          stop_threshold = (
            self.system_v3_stop_threshold_rapid_futures
            if is_futures_mode
            else self.system_v3_stop_threshold_rapid_spot
          )
        else:
          stop_enabled = stops_enable
          stop_threshold = self.stop_threshold_rapid_futures if is_futures_mode else self.stop_threshold_rapid_spot

        if stop_enabled:
          stoploss_value = -(entry_cost * stop_threshold / leverage)

          if is_system_v3 or is_system_v3_1 or is_system_v3_2:
            if profit_stake < stoploss_value:
              sell, signal_name = True, f"exit_{mode}_stoploss_doom"
          elif profit_stake < stoploss_value and (
            is_backtest or trade.open_date_utc.replace(tzinfo=None) >= datetime(2024, 9, 13)
          ):
            sell, signal_name = True, f"exit_{mode}_stoploss_doom"

    # Profit Target Signal
    if pair_cache:
      previous_rate = pair_cache["rate"]
      previous_time_profit_reached = datetime.fromisoformat(pair_cache["time_profit_reached"])

      sell_max, signal_name_max = exit_profit_target(
        mode,
        pair,
        trade,
        current_time,
        current_rate,
        profit_stake,
        profit_ratio,
        profit_current_stake_ratio,
        profit_init_ratio,
        last_candle,
        previous_candle_1,
        previous_rate,
        previous_profit,
        previous_sell_reason,
        previous_time_profit_reached,
        enter_tags,
      )

      if sell_max and signal_name_max is not None:
        return True, f"{signal_name_max}_m"

      if previous_sell_reason == f"exit_{mode}_stoploss_u_e":
        if profit_ratio > (previous_profit + 0.001):
          mark_pair, mark_signal = mark_profit_target(
            mode,
            pair,
            True,
            previous_sell_reason,
            trade,
            current_time,
            current_rate,
            profit_ratio,
            last_candle,
            previous_candle_1,
          )

          if mark_pair:
            set_profit_target(
              pair,
              mark_signal,
              current_rate,
              profit_ratio,
              current_time,
            )

      elif profit_init_ratio > (previous_profit + 0.001) and previous_sell_reason != f"exit_{mode}_stoploss_doom":
        mark_pair, mark_signal = mark_profit_target(
          mode,
          pair,
          True,
          previous_sell_reason,
          trade,
          current_time,
          current_rate,
          profit_init_ratio,
          last_candle,
          previous_candle_1,
        )

        if mark_pair:
          set_profit_target(
            pair,
            mark_signal,
            current_rate,
            profit_init_ratio,
            current_time,
          )

    # Add the pair to the list, if a sell triggered and conditions met
    if sell and signal_name is not None:
      protected_signals = {
        f"exit_{mode}_stoploss_doom",
        f"exit_{mode}_stoploss_u_e",
      }

      blocked_previous_signals = {
        f"exit_{mode}_stoploss_doom",
        f"exit_profit_{mode}_stoploss_u_e",
      }

      if signal_name in protected_signals and previous_sell_reason not in blocked_previous_signals:
        mark_pair, mark_signal = mark_profit_target(
          mode,
          pair,
          sell,
          signal_name,
          trade,
          current_time,
          current_rate,
          profit_ratio,
          last_candle,
          previous_candle_1,
        )

        if mark_pair:
          set_profit_target(
            pair,
            mark_signal,
            current_rate,
            profit_ratio,
            current_time,
          )
        else:
          return True, signal_name

      elif previous_profit is None or previous_profit < profit_init_ratio:
        mark_pair, mark_signal = mark_profit_target(
          mode,
          pair,
          sell,
          signal_name,
          trade,
          current_time,
          current_rate,
          profit_init_ratio,
          last_candle,
          previous_candle_1,
        )

        if mark_pair:
          set_profit_target(
            pair,
            mark_signal,
            current_rate,
            profit_init_ratio,
            current_time,
          )
        else:
          return True, signal_name

    elif profit_init_ratio >= 0.005:
      if previous_profit is None or previous_profit < profit_init_ratio:
        set_profit_target(
          pair,
          f"exit_profit_{mode}_max",
          current_rate,
          profit_init_ratio,
          current_time,
        )

    ignored_signals = {
      f"exit_profit_{mode}_max",
      f"exit_{mode}_stoploss_doom",
      f"exit_{mode}_stoploss_u_e",
    }

    if sell and signal_name is not None and signal_name not in ignored_signals:
      return True, signal_name

    # Here ends exit signal conditions for long_exit_rapid
    return False, None

