  # Short Exit Stop Loss
  # ---------------------------------------------------------------------------------------------
  def short_exit_stoploss(
    self,
    mode_name: str,
    current_rate: float,
    profit_stake: float,
    profit_ratio: float,
    profit_current_stake_ratio: float,
    profit_init_ratio: float,
    max_profit: float,
    max_loss: float,
    filled_orders,
    filled_entries,
    filled_exits,
    last_candle,
    previous_candle_1,
    trade: "Trade",
    current_time: "datetime",
    buy_tag,
  ) -> tuple:
    is_futures_mode = self.is_futures_mode
    doom_stops_enable = self.doom_stops_enable
    trade_leverage = trade.leverage
    stoploss_doom = f"exit_{mode_name}_stoploss_doom"
    stoploss_u_e = f"exit_{mode_name}_stoploss_u_e"

    is_backtest = self.is_backtest_mode()
    trade_open_date = None if is_backtest else trade.open_date_utc.replace(tzinfo=None)
    is_system_v3, is_system_v3_1, is_system_v3_2 = self.get_system_version_flags(trade)
    is_system_v4 = self.is_system_v4(trade)
    if not self.stops_enable:
      return False, None

    entry_cost = filled_entries[0].safe_filled * filled_entries[0].safe_price
    if is_system_v4:
      # Stoploss doom
      if self.system_v4_stops_enable and (
        profit_stake
        < -(
          entry_cost
          * (
            self.system_v4_stop_threshold_doom_futures if is_futures_mode else self.system_v4_stop_threshold_doom_spot
          )
          / trade_leverage
        )
      ):
        return True, stoploss_doom
    elif is_system_v3_2:
      # Stoploss doom
      if self.system_v3_2_stops_enable and (
        profit_stake
        < -(
          entry_cost
          * (
            self.system_v3_2_stop_threshold_doom_futures
            if is_futures_mode
            else self.system_v3_2_stop_threshold_doom_spot
          )
          / trade_leverage
        )
      ):
        return True, stoploss_doom
    elif is_system_v3_1:
      # Stoploss doom
      if doom_stops_enable and (
        profit_stake
        < -(
          entry_cost
          * (
            self.system_v3_1_stop_threshold_doom_futures
            if is_futures_mode
            else self.system_v3_1_stop_threshold_doom_spot
          )
          / trade_leverage
        )
      ):
        return True, stoploss_doom
    elif is_system_v3:
      # Stoploss doom
      if doom_stops_enable and (
        profit_stake
        < -(
          entry_cost
          * (
            self.system_v3_stop_threshold_doom_futures if is_futures_mode else self.system_v3_stop_threshold_doom_spot
          )
          / trade_leverage
        )
      ):
        return True, stoploss_doom
    else:
      # Stoploss doom
      if (
        doom_stops_enable
        and (
          profit_stake
          < -(entry_cost * (self.stop_threshold_doom_futures if is_futures_mode else self.stop_threshold_doom_spot))
        )
        and (
          self.has_valid_entry_conditions(trade, current_rate, last_candle, previous_candle_1, filled_orders) == False
        )
        # temporary
        and (is_backtest or trade_open_date >= datetime(2024, 9, 13))
      ):
        return True, stoploss_doom

    last_close = last_candle["close"]
    last_ema_200 = last_candle["EMA_200"]
    last_rsi_14 = last_candle["RSI_14"]
    last_cmf_20 = last_candle["CMF_20"]
    last_rsi_14_1h = last_candle["RSI_14_1h"]
    previous_rsi_14 = previous_candle_1["RSI_14"]

    # Stoploss u_e
    if (
      self.u_e_stops_enable
      and (
        profit_stake
        < -(
          entry_cost * (self.stop_threshold_futures if is_futures_mode else self.stop_threshold_spot)
          # / trade.leverage
        )
      )
      and (last_close > last_ema_200)
      and (last_cmf_20 > 0.0)
      and (((last_close - last_ema_200) / last_ema_200) < 0.010)
      and (last_rsi_14 < previous_rsi_14)
      and (last_rsi_14 < (last_rsi_14_1h - 24.0))
      # and (current_time - timedelta(minutes=720) > trade.open_date_utc)
      # temporary
      and (is_backtest or trade_open_date >= datetime(2025, 4, 3))
    ):
      return True, stoploss_u_e

    #  Here ends exit signal conditions for short_exit_stoploss

    return False, None

